#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int *rooms = (int *)malloc(sizeof(int) * n);
    if (rooms == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &rooms[i]) != 1) {
            return 1;
        }
    }

    int total = 0;
    for (int i = 0; i < n; i++) {
        printf("第 %d 间：%d 条小鱼干\n", i, rooms[i]);
        total += rooms[i];
    }
    printf("一共 %d 条小鱼干\n", total);

    free(rooms);
    rooms = NULL;
    return 0;
}

